// JVM Arguments to capture heap dump on failure
-Xmx4g -Xms4g -XX:+HeapDumpOnOutOfMemoryError -XX:HeapDumpPath=/var/log/app/heapdump.hprof

// Example of a common leak: A static map that never clears
public class CacheManager {
    private static final Map<String, Object> CACHE = new ConcurrentHashMap<>();

    public void addToCache(String key, Object value) {
        // If this map grows indefinitely without an eviction policy, 
        // it will eventually trigger an OOM.
        CACHE.put(key, value);
    }
}
